const item = $input.first();
const input = item.json;
const cv = item.binary?.cv;
const text = (value) => typeof value === 'string' ? value.trim() : '';
const rawJobInput = text(input.job_description);
const company_name = text(input.company_name);
const githubInput = text(input.github_profile);
const errors = [];
let job_description = '';
let job_url = '';
const hasHttpScheme = /^https?:\/\//i.test(rawJobInput);
if (hasHttpScheme) {
  try {
    const parsed = new URL(rawJobInput);
    if (!['http:', 'https:'].includes(parsed.protocol) || !parsed.hostname || parsed.username || parsed.password || (parsed.port && !['80', '443'].includes(parsed.port))) throw new Error('invalid URL');
    job_url = rawJobInput;
  } catch (error) {
    errors.push('Please provide a valid public job-posting URL or paste the job description.');
  }
} else {
  job_description = rawJobInput;
}
if (!company_name) errors.push('Please provide the company name.');
if (!job_description && !job_url) errors.push('Please provide a job-posting URL or paste the job description.');
if (job_description.length > 20000) errors.push('The pasted job description must be 20,000 characters or fewer.');
if (job_url.length > 2048) errors.push('The job-posting URL must be 2,048 characters or fewer.');
if (!cv && !githubInput) errors.push('Please upload a PDF CV or provide a GitHub profile.');
if (cv && cv.mimeType !== 'application/pdf' && !/\.pdf$/i.test(cv.fileName ?? '')) errors.push('The uploaded CV must be a PDF.');
let github_username = '';
if (githubInput) {
  const match = githubInput.match(/^(?:https?:\/\/)?(?:www\.)?github\.com\/([A-Za-z0-9-]{1,39})\/?$/i) ?? githubInput.match(/^([A-Za-z0-9-]{1,39})$/);
  if (!match) errors.push('GitHub must be a username or a GitHub profile URL.');
  else github_username = match[1];
}
return [{ json: { company_name, job_description, job_url, github_username, has_cv: Boolean(cv), has_github: Boolean(github_username), validation_ok: errors.length === 0, validation_error: errors[0] ?? '' }, binary: item.binary }];

const validated = $('Validate Input').first();
const original = validated.json;
const input = $input.first().json;

const toText = (s) => String(s ?? '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/gi, "'")
  .replace(/\s+/g, ' ')
  .trim();

let job_description = String(original.job_description ?? '').trim();

if (!job_description && original.job_url) {
  const raw = typeof input === 'string' ? input : (input.data ?? input.body ?? input.response ?? '');
  const html = String(raw).slice(0, 500000);   // never process more than 500k characters

  // 1) Structured job data (JSON-LD "JobPosting")
  const blocks = html.match(/<script[^>]*application\/ld\+json[^>]*>[\s\S]*?<\/script>/gi) || [];
  for (const block of blocks) {
    try {
      const data = JSON.parse(block.replace(/^<script[^>]*>/i, '').replace(/<\/script>$/i, ''));
      const list = Array.isArray(data) ? data : (data['@graph'] ?? [data]);
      const posting = list.find((x) => x && x['@type'] === 'JobPosting');
      if (posting) {
        job_description = `${posting.title ?? ''}\n${toText(posting.description)}`.trim();
        break;
      }
    } catch (e) { /* skip broken JSON */ }
  }

  // 2) Fallback: the page's short description (og:description)
  if (job_description.length < 50) {
    const og = html.match(/<meta[^>]*property="og:description"[^>]*content="([^"]*)"/i);
    job_description = toText(og?.[1] ?? '');
  }

  job_description = job_description.slice(0, 20000);
  if (job_description.length < 50) {
    throw new Error('The job advertisement could not be read. Please paste the job description instead.');
  }
}

if (!job_description) throw new Error('No usable job description was provided');
return [{ json: { ...original, job_description }, binary: validated.binary }];

const validated = $('Validate Input').first().json;
const itemsFrom = (name) => {
  try { return $(name).all(); } catch (error) { return []; }
};
const notes = [];
let cvText = '';
if (validated.has_cv) {
  cvText = String(itemsFrom('Extract CV Text')[0]?.json?.text ?? '').trim();
  if (cvText.length < 50) {
    cvText = '';
    notes.push('The CV could not be read, so it was not used.');
  }
}
const candidate_text = cvText.slice(0, 30000);
const repoItems = validated.has_github ? itemsFrom('GitHub Repositories').map((item) => item.json) : [];
const readmeItems = validated.has_github ? itemsFrom('GitHub Repository READMEs') : [];
const github_repositories = repoItems
  .filter((repo) => repo.name && repo.html_url && !repo.fork)
  .map((repo, index) => {
    const readmeJson = readmeItems[index]?.json;
    const readme = typeof readmeJson === 'string'
      ? readmeJson
      : String(readmeJson?.data ?? readmeJson?.body ?? '');
    return {
      name: repo.name,
      description: repo.description ?? '',
      language: repo.language ?? '',
      topics: repo.topics ?? [],
      stars: repo.stargazers_count ?? 0,
      last_pushed: repo.pushed_at ?? '',
      url: repo.html_url,
      readme: readme.slice(0, 12000)
    };
  });
if (validated.has_github && github_repositories.length === 0) {
  notes.push('No public GitHub repositories were available, so GitHub was not used.');
}
if (validated.has_github && readmeItems.length === 0 && github_repositories.length > 0) {
  notes.push('Repository metadata was available, but README content could not be retrieved.');
}
if (!candidate_text && github_repositories.length === 0) {
  throw new Error('No usable candidate evidence was found in the CV or GitHub profile');
}
return [{ json: { candidate_text, github_repositories, data_notes: notes } }];

