const content = $input.first().json.choices?.[0]?.message?.content;
if (typeof content !== 'string' || !content.trim()) {
  throw new Error('The model response did not contain report content');
}
let report;
try {
  report = JSON.parse(content);
} catch (error) {
  throw new Error(`The model returned invalid JSON: ${error.message}`);
}
const required = ['company_background', 'recent_news', 'role_requirements', 'experience_match', 'projects_to_highlight', 'skill_gaps', 'interview_questions'];
for (const field of required) {
  if (!(field in report)) throw new Error(`Report is missing required section: ${field}`);
}
if (!Array.isArray(report.interview_questions) || report.interview_questions.length !== 5) {
  throw new Error('Report must contain exactly five interview questions');
}
if (!Array.isArray(report.recent_news) || report.recent_news.length > 3) {
  throw new Error('Report must contain zero to three recent news items');
}
for (const field of ['experience_match', 'projects_to_highlight']) {
  if (!Array.isArray(report[field])) throw new Error(`Report section ${field} must be an array`);
}
if (typeof report.company_background !== 'object' || report.company_background === null || typeof report.company_background.summary !== 'string') {
  throw new Error('Report section company_background must contain a summary');
}

const normalizeUrl = (url) => String(url ?? '').trim().toLowerCase().replace(/#.*$/, '').replace(/\/+$/, '');
const normalizeText = (value) => String(value ?? '')
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[‘’]/g, "'")
  .replace(/[“”]/g, '"')
  .replace(/[–—]/g, '-')
  .replace(/[^a-z0-9]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
const evidenceTokens = (value) => normalizeText(value).split(' ').filter((token) => token.length > 2);

const research = $('Company Research and News').first().json;
const researchUrls = new Set((Array.isArray(research.results) ? research.results : []).map((result) => normalizeUrl(result.url)));
const evidence = $('Build Candidate Evidence').first().json;
const candidateText = normalizeText(evidence.candidate_text);
const repositoryUrls = new Set((Array.isArray(evidence.github_repositories) ? evidence.github_repositories : []).map((repo) => normalizeUrl(repo.url)));
const removed_claims = [];

const background = report.company_background;
const backgroundUrls = Array.isArray(background.source_urls) ? background.source_urls : [];
background.source_urls = backgroundUrls.filter((url) => researchUrls.has(normalizeUrl(url)));
for (const url of backgroundUrls) {
  if (!researchUrls.has(normalizeUrl(url))) removed_claims.push({ section: 'company_background', reason: 'Source URL was not in the search results', value: url });
}
if (background.source_urls.length === 0) {
  background.summary = 'Public information about this company is limited.';
}

report.recent_news = report.recent_news.filter((news) => {
  const verified = researchUrls.has(normalizeUrl(news?.url));
  if (!verified) removed_claims.push({ section: 'recent_news', reason: 'News URL was not in the search results', value: news?.url ?? '' });
  return verified;
});

const hasEvidence = (claim) => {
  if (claim?.evidence_source === 'github') return repositoryUrls.has(normalizeUrl(claim.evidence_url));
  if (claim?.evidence_source === 'candidate_text') {
    const quote = normalizeText(claim.evidence_quote);
    if (quote.length < 8 || !candidateText) return false;
    if (candidateText.includes(quote)) return true;
    const quoteTokens = evidenceTokens(quote);
    const candidateTokens = new Set(evidenceTokens(candidateText));
    const matchedTokens = quoteTokens.filter((token) => candidateTokens.has(token)).length;
    return quoteTokens.length >= 4 && matchedTokens / quoteTokens.length >= 0.8;
  }
  return false;
};
for (const section of ['experience_match', 'projects_to_highlight']) {
  report[section] = report[section].filter((claim) => {
    const verified = hasEvidence(claim);
    if (!verified) removed_claims.push({ section, reason: 'Evidence could not be traced to the CV, candidate text, or GitHub', value: claim?.requirement ?? claim?.project ?? '' });
    return verified;
  });
}

return [{ json: { report, validation: { removed_claims, data_notes: evidence.data_notes } } }];

const report = $json.report ?? {};
const evidence = $('Build Candidate Evidence').first().json ?? {};
const repositories = Array.isArray(evidence.github_repositories) ? evidence.github_repositories : [];
const normalize = (value) => String(value ?? '').toLowerCase().replace(/[–—]/g, '-').replace(/\s+/g, ' ').trim();
const tokens = (value) => normalize(value).replace(/[^a-z0-9\s-]/g, ' ').split(/\s+/).filter((token) => token.length > 2).map((token) => token.replace(/ies$/, 'y').replace(/(ing|ed|s)$/, ''));
const meaningfullyMatches = (left, right) => {
  const a = normalize(left);
  const b = normalize(right);
  if (!a || !b) return false;
  if (a.includes(b) || b.includes(a)) return true;
  const leftTokens = [...new Set(tokens(a))];
  const rightTokens = [...new Set(tokens(b))];
  const shared = leftTokens.filter((token) => rightTokens.includes(token)).length;
  return shared >= 2 && shared / Math.max(1, Math.min(leftTokens.length, rightTokens.length)) >= 0.5;
};
const added_projects = [];
const added_gaps = [];
report.projects_to_highlight = Array.isArray(report.projects_to_highlight) ? report.projects_to_highlight : [];
const projectUrls = new Set(report.projects_to_highlight.map((item) => normalize(item.evidence_url)));
if (report.projects_to_highlight.length < 2) {
  for (const repo of repositories) {
    const signal = String(repo.readme ?? repo.description ?? (Array.isArray(repo.topics) ? repo.topics.join(', ') : '')).trim();
    const url = String(repo.url ?? '').trim();
    if (!repo.name || !url || !signal || projectUrls.has(normalize(url))) continue;
    report.projects_to_highlight.push({
      project: repo.name,
      candidate_role: 'GitHub project',
      context: 'Public GitHub repository',
      why_relevant: 'Repository evidence available for discussion: ' + signal.slice(0, 260),
      talking_point: 'Explain the problem, your contribution, key decisions, and outcome using details you can substantiate.',
      evidence_source: 'github',
      evidence_quote: '',
      evidence_url: url
    });
    projectUrls.add(normalize(url));
    added_projects.push(repo.name);
    if (report.projects_to_highlight.length >= 2) break;
  }
}
const requirements = Array.isArray(report.role_requirements) ? report.role_requirements : [];
const matches = Array.isArray(report.experience_match) ? report.experience_match : [];
const matchText = matches.map((item) => normalize(item.requirement));
const gapText = (Array.isArray(report.skill_gaps) ? report.skill_gaps : []).map((item) => normalize(typeof item === 'string' ? item : item?.gap));
report.skill_gaps = Array.isArray(report.skill_gaps) ? report.skill_gaps : [];
for (const item of requirements) {
  if (report.skill_gaps.length >= 3) break;
  const requirement = typeof item === 'string' ? item : String(item?.requirement ?? '');
  const key = normalize(requirement);
  if (!key) continue;
  const matched = matchText.some((match) => meaningfullyMatches(match, key));
  const alreadyGap = gapText.some((gap) => meaningfullyMatches(gap, key));
  if (matched || alreadyGap) continue;
  report.skill_gaps.push({
    gap: 'No validated candidate evidence for: ' + requirement,
    preparation_step: 'Prepare a truthful example, transferable experience, or concise explanation of how you would approach this requirement.'
  });
  gapText.push(key);
  added_gaps.push(requirement);
}
return [{ json: { ...$json, report, validation: { ...($json.validation ?? {}), added_projects, added_gaps } } }];
